INSERT INTO sim_testpack.test_cases (test_id, area, title, role, preconditions, steps, expected, data_file, priority) VALUES
  ('SIM-001', 'Settings', 'Add the 26 SIM providers', 'Administrator', 'make seed-demo (or an empty DB with an admin); signed in', 'Administration → Settings → SIM providers: add each provider of settings_sim_providers.csv with its e-mail and default plan; choose Telia LT as the default; Non-return Value 30.00 €. Or PUT settings_sim_providers.request.json to /api/v1/settings/sim-providers', 'Settings lists 26 providers in order, Telia LT chosen first, 30.00 €', 'settings_sim_providers.csv', 'P0'),
  ('SIM-002', 'Settings', 'Provider e-mails go nowhere real', 'Administrator', 'SIM-001 done', 'Open a provider''s e-mail on Settings', 'Every address is …@example.com, so a test e-mail never reaches an operator', 'settings_sim_providers.csv', 'P0'),
  ('SIM-003', 'Import', 'Check the Lithuania SIM list without writing', 'Administrator', 'SIM-001 done; make seed-demo (for the holders)', 'make import-sims FILE=docs/test-packs/sim-cards-baltics-poland/import/sim-import-lt.csv', 'Each card is listed with its status and holder; nothing is written; no problems', 'import/sim-import-lt.csv', 'P0'),
  ('SIM-004', 'Import', 'Check the Latvia SIM list without writing', 'Administrator', 'SIM-001 done; make seed-demo (for the holders)', 'make import-sims FILE=docs/test-packs/sim-cards-baltics-poland/import/sim-import-lv.csv', 'Each card is listed with its status and holder; nothing is written; no problems', 'import/sim-import-lv.csv', 'P0'),
  ('SIM-005', 'Import', 'Check the Estonia SIM list without writing', 'Administrator', 'SIM-001 done; make seed-demo (for the holders)', 'make import-sims FILE=docs/test-packs/sim-cards-baltics-poland/import/sim-import-ee.csv', 'Each card is listed with its status and holder; nothing is written; no problems', 'import/sim-import-ee.csv', 'P0'),
  ('SIM-006', 'Import', 'Check the Poland SIM list without writing', 'Administrator', 'SIM-001 done; make seed-demo (for the holders)', 'make import-sims FILE=docs/test-packs/sim-cards-baltics-poland/import/sim-import-pl.csv', 'Each card is listed with its status and holder; nothing is written; no problems', 'import/sim-import-pl.csv', 'P0'),
  ('SIM-007', 'Import', 'Import all four countries', 'Administrator', 'SIM-003…006 pass', 'make import-sims FILE=…/import/sim-import-all.csv COMMIT=yes', '91 SIM cards added in one go; held ones given to their employee with no form; Available and Not Activated in the Office', 'import/sim-import-all.csv', 'P0'),
  ('SIM-008', 'Import', 'Semicolons, a byte order mark and columns in another order', 'Administrator', 'an empty register (or before SIM-007)', 'make import-sims FILE=…/import/sim-import-all-semicolon-bom.csv', 'Read the same as the comma file: same cards, no problems', 'import/sim-import-all-semicolon-bom.csv', 'P1'),
  ('SIM-009', 'Import', 'Running the import twice imports nothing', 'Administrator', 'SIM-007 done', 'Run SIM-007''s command again', 'Refused: every SIM No. is already registered; nothing written', 'import/sim-import-all.csv', 'P1'),
  ('SIM-010', 'Import', 'Every problem is listed, nothing written', 'Administrator', 'SIM-007 done', 'make import-sims FILE=…/import/sim-import-errors.csv', 'Nothing is written. First pass: lines 2-4 named (Available with a holder, unknown employee, unknown status). Delete them and run again: the unknown provider is only noted, line 6 refused (not a phone number), and after SIM-007 line 5 (SIM No. already registered)', 'import/sim-import-errors.csv', 'P0'),
  ('SIM-011', 'SIM Cards', 'Tabs count and filter by status', 'Manager', 'SIM-007 done', 'Company Assets → SIM Cards; open each tab', 'Counts match sim_cards.csv''s statuses (Available counts as Active)', 'sim_cards.csv', 'P1'),
  ('SIM-012', 'SIM Cards', 'Phone numbers of four countries', 'Manager', 'SIM-007 done', 'Open an LV, an EE and a PL card', 'Phone No. shown as written (+371 …, +372 …, +48 …)', 'sim_cards.csv', 'P1'),
  ('SIM-013', 'SIM Cards', 'Find a card by number in ⌘K', 'Manager', 'SIM-007 done', '⌘K, type the last 6 digits of a SIM No.', 'The card is found and opens beside the register', 'sim_cards.csv', 'P2'),
  ('SIM-014', 'Add SIM', 'Add SIM by hand for each country', 'Manager', 'SIM-001 done', 'Add SIM with a SIM No. of block 3 (any provider) from add_sim_manual.csv', 'Added Not Activated in the Office, provider''s default plan and the 30.00 € value filled in', 'add_sim_manual.csv', 'P1'),
  ('SIM-015', 'Add SIM', 'A prepaid card', 'Manager', 'SIM-001 done', 'Add SIM, provider Labas (or any prepaid brand)', 'The plan is the brand''s prepaid plan from Settings', 'add_sim_manual.csv', 'P1'),
  ('SIM-016', 'Give and return', 'Give SIM against a printed form', 'Manager', 'an Active card in the Office', 'Give SIM to Ona Kazlauskienė; print the form; Upload Signed Form (any PDF)', 'Given; form printed with provider, plan, phone and value; signed copy listed', 'sim_cards.csv', 'P0'),
  ('SIM-017', 'Give and return', 'Print Form for an imported held card', 'Manager', 'SIM-007 done; Edit the card''s Non-return Value first', 'Open a held card from the import → ⋯ → Print Form', 'Without a value it says so; with one it prints, dated 2026-08-03; asset.form_printed recorded', 'sim_cards.csv', 'P1'),
  ('SIM-018', 'Give and return', 'Return and Mark as Not Returned', 'Manager', 'two given cards', 'Return one; Mark the other as Not Returned with a reason', 'The first is back in the Office; the second shows Not Returned; neither status changed', 'sim_cards.csv', 'P1'),
  ('SIM-019', 'Status', 'Change Status never moves the card', 'Manager', 'a given Active card', 'Change Status → Blocked', 'Blocked, still with its holder', 'sim_cards.csv', 'P1'),
  ('SIM-020', 'E-mails', 'Prepare Activation Email', 'Manager', 'a Not Activated card; Mail Templates set', 'Open the card → Prepare Activation Email', 'To is the provider''s example.com address, the card''s numbers filled in; Send Email only opens your mail app', 'settings_sim_providers.csv', 'P1'),
  ('SIM-021', 'E-mails', 'Prepare Blocking Email', 'Manager', 'an Active card', 'Prepare Blocking Email', 'As above, the blocking template', 'settings_sim_providers.csv', 'P2'),
  ('SIM-022', 'Scan SIMs', 'Scan the valid printed cards', 'Manager', 'SIM-001 done; scan_cards.html printed or on a second screen', 'Open /apps/sim-scan/; For every SIM: provider; photograph front and back of SC-001…SC-052 (by provider)', 'Each SIM No. read from the Code 128 barcode, never the EAN-13; PIN and PUK read; Add adds them all', 'scan_cards.csv', 'P0'),
  ('SIM-023', 'Scan SIMs', 'The review list marks every problem', 'Manager', 'SIM-007 done', 'Scan SC-053…SC-060', 'Check digit, duplicate, …5F, PIN, PUK and registered cards are marked; Add refuses until fixed', 'scan_cards.csv', 'P0'),
  ('SIM-024', 'Scan SIMs', 'Show PIN and PUK', 'Manager', 'cards added by SIM-022; a recent sign-in', 'Show PIN and PUK; find a card by number', 'Asks for your password if the sign-in is not recent; shows the codes from scan_cards.csv; recorded as asset.sim_codes_shown', 'scan_cards.csv', 'P0'),
  ('SIM-025', 'Access', 'An employee sees no SIM cards', 'Employee', 'an Employee user', 'Sign in as the employee; open /assets/sim-cards', 'Company Assets is not offered; the API answers 403', '', 'P1'),
  ('SIM-026', 'Audit', 'Every change is in the Changes', 'Administrator', 'the steps above done', 'Open a card → Changes; Administration → Audit log, filter asset.*', 'asset.registered, asset.given, asset.returned, asset.status_changed … with who and when', '', 'P2');
