-- SIM card test pack (demo data). A standalone schema for reference and reports;
-- PPE itself takes SIM cards through import/ and Settings, never through these tables.
BEGIN;
CREATE SCHEMA IF NOT EXISTS sim_testpack;

DROP TABLE IF EXISTS sim_testpack.operators;
CREATE TABLE sim_testpack.operators (
  operator_id text,
  country_code text,
  country text,
  operator text,
  legal_entity text,
  mcc_mnc text,
  network text,
  website text,
  ppe_provider_name text,
  dialling_code text,
  currency text,
  vat_rate_pct integer,
  iccid_prefix text
);

DROP TABLE IF EXISTS sim_testpack.brands;
CREATE TABLE sim_testpack.brands (
  brand_id text,
  operator_id text,
  country_code text,
  brand text,
  kind text,
  segment text,
  website text,
  official_color_hex text,
  color_status text,
  logo_description text,
  logo_source text,
  trademark_note text,
  demo_badge_color text,
  demo_badge_text text,
  ppe_provider_name text
);

DROP TABLE IF EXISTS sim_testpack.plans;
CREATE TABLE sim_testpack.plans (
  plan_id text,
  operator_id text,
  brand_id text,
  country_code text,
  plan_name text,
  segment text,
  plan_type text,
  data_gb text,
  minutes text,
  sms text,
  eu_roaming_gb text,
  monthly_price numeric(10,2),
  monthly_price_ex_vat numeric(10,2),
  currency text,
  vat_rate_pct integer,
  contract_months integer,
  sim_fee numeric(10,2),
  esim text,
  ppe_plan_label text,
  is_demo text
);

DROP TABLE IF EXISTS sim_testpack.prepaid_offers;
CREATE TABLE sim_testpack.prepaid_offers (
  offer_id text,
  brand_id text,
  operator_id text,
  country_code text,
  brand text,
  offer_name text,
  offer_type text,
  data_gb text,
  minutes text,
  sms text,
  validity_days integer,
  price numeric(10,2),
  included_credit numeric(10,2),
  currency text,
  vat_rate_pct integer,
  eu_roaming text,
  registration_required text,
  esim text,
  is_demo text
);

DROP TABLE IF EXISTS sim_testpack.services;
CREATE TABLE sim_testpack.services (
  service_id text,
  operator_id text,
  country_code text,
  service_name text,
  category text,
  billing text,
  price numeric(10,2),
  price_ex_vat numeric(10,2),
  currency text,
  applies_to text,
  is_demo text
);

DROP TABLE IF EXISTS sim_testpack.settings_sim_providers;
CREATE TABLE sim_testpack.settings_sim_providers (
  name text,
  email text,
  default_plan text,
  country_code text,
  operator_id text,
  prepaid text
);

DROP TABLE IF EXISTS sim_testpack.sim_cards;
CREATE TABLE sim_testpack.sim_cards (
  sim_no text,
  phone_no text,
  provider text,
  employee_name text,
  connection_status text,
  country_code text,
  operator_id text,
  brand_id text,
  prepaid text,
  plan text,
  pin text,
  puk text,
  expected text
);

DROP TABLE IF EXISTS sim_testpack.scan_cards;
CREATE TABLE sim_testpack.scan_cards (
  card_id text,
  sim_no text,
  barcode text,
  pin text,
  puk text,
  ean13_product_code text,
  provider text,
  country_code text,
  prepaid text,
  case text,
  expected text
);

DROP TABLE IF EXISTS sim_testpack.add_sim_manual;
CREATE TABLE sim_testpack.add_sim_manual (
  sim_no text,
  provider text,
  phone_no text,
  country_code text,
  prepaid text
);

DROP TABLE IF EXISTS sim_testpack.test_cases;
CREATE TABLE sim_testpack.test_cases (
  test_id text,
  area text,
  title text,
  role text,
  preconditions text,
  steps text,
  expected text,
  data_file text,
  priority text
);

DROP TABLE IF EXISTS sim_testpack.sim_samples;
CREATE TABLE sim_testpack.sim_samples (
  sample_id text,
  brand_id text,
  brand text,
  kind text,
  operator text,
  operator_id text,
  country_code text,
  provider text,
  form text,
  sim_no text,
  phone_no text,
  pin text,
  puk text,
  pin2 text,
  puk2 text,
  imsi text,
  esim_activation_code text,
  plan text,
  plan_type text,
  price numeric(10,2),
  currency text,
  price_period text,
  connection_status text,
  demo_badge_color text,
  demo_badge_text text,
  is_demo text
);

COMMIT;
